const icon = (name, attrs = "") => `<svg viewBox="0 0 24 24" fill="currentColor" aria-hidden="true" ${attrs}>${ICON[name] || ""}</svg>`;
const PAGES = [
  ["", [["home", "Home"], ["dashboard", "Dashboard"]]],
  ["Requests", [["workspace", "Workflow experimentation"], ["results", "Workflow results"], ["history", "Execution history"]]],
  ["Federation", [["organizations", "Organizations and servers"], ["tools", "Tools catalog"], ["descriptors", "Service descriptors"], ["connectors", "Live MCP connectors"], ["explorer", "Organizations explorer"]]],
  ["Preparation", [["preparation", "Preparation center"], ["governance", "Sharing and governance"]]],
  ["System", [["model", "Language model"], ["environment", "Configuration"], ["about", "About"]]],
];
const TITLES = Object.fromEntries(PAGES.flatMap(([g, ps]) => ps.map(([id, t]) => [id, [g, t]])));
const UI = { page: "home", exFilter: { q: "", country: "", lang: "text" }, toolPage: 0, gov: { orgs: null }, descSel: null, toolFilter: { q: "", org: "", cap: "", cert: "", maxLatency: "", minDep: "", sort: "name", dir: 1 }, descFilter: { q: "", org: "" }, selOrg: null, prepTab: "cards", prepHost: "h-portal", probe: {}, selRun: null, step: 1, histFilter: { q: "", type: "", from: "", to: "", status: "" }, explorer: { org: "", cap: "", cat: "" }, matrix: { purpose: "notification", category: "LOC" }, envTab: "domain", taskSel: null };
const prov = (kind, label) => `<span class="prov ${kind}" title="${esc({ configured: "Configured in this portal", declared: "Declared by the provider", certified: "Certified", audited: "Audited", simulated: "Produced by the simulation backend", observed: "Observed from portal activity", live: "Produced by a live model call" }[kind] || kind)}">${esc(label || { configured: "Configured", declared: "Provider-declared", certified: "Certified", audited: "Audited", simulated: "Simulated", observed: "Observed", live: "Live model" }[kind])}</span>`;
const certChip = t => { const c = t.certification; return c.status === "certified" ? prov("certified", c.basis === "audit" ? "Certified (audit)" : "Certified") : c.status === "rejected" ? `<span class="st bad">Rejected by audit</span>` : `<span class="st warn">Not certified</span>`; };

/* ----------------------------------------------------------- toasts, dialogs */
function toast(msg, bad) { const a = document.getElementById("toasts"); const d = document.createElement("div"); d.className = "toast" + (bad ? " bad" : ""); d.textContent = msg; d.setAttribute("role", "status"); a.appendChild(d); setTimeout(() => d.remove(), 3800); }
function confirmDialog(text, okLabel, onOk) {
  const w = document.createElement("div"); w.className = "dialog-wrap";
  w.innerHTML = `<div class="dialog" role="alertdialog" aria-modal="true" aria-labelledby="dlg-t"><h3 id="dlg-t">${esc(text)}</h3><p class="muted small">This cannot be undone.</p><div class="row" style="justify-content:flex-end;margin-top:12px"><button class="btn" data-x="no">Cancel</button><button class="btn danger" data-x="yes">${esc(okLabel)}</button></div></div>`;
  document.body.appendChild(w); w.querySelector('[data-x="no"]').focus();
  w.addEventListener("click", e => { const x = e.target.getAttribute("data-x"); if (x === "yes") { w.remove(); onOk(); } else if (x === "no" || e.target === w) w.remove(); });
  w.addEventListener("keydown", e => { if (e.key === "Escape") w.remove(); });
}
function openDrawer(title, body, onSave, saveLabel = "Save changes", extra = "") {
  closeDrawer();
  const w = document.createElement("div"); w.className = "scrim"; w.id = "drawer";
  w.innerHTML = `<aside class="drawer" role="dialog" aria-modal="true" aria-label="${esc(title)}"><div class="drawer-h"><h2 style="margin:0">${esc(title)}</h2><span class="spacer"></span><button class="btn ghost" data-x="close" aria-label="Close">✕</button></div><form class="drawer-b" novalidate>${body}</form><div class="drawer-f">${extra}<span class="spacer"></span><button class="btn" data-x="close">Cancel</button>${onSave ? `<button class="btn primary" data-x="save">${esc(saveLabel)}</button>` : ""}</div></aside>`;
  document.body.appendChild(w);
  const form = w.querySelector("form");
  w.addEventListener("click", e => { const x = e.target.closest("[data-x]"); if (e.target === w || (x && x.dataset.x === "close")) closeDrawer(); if (x && x.dataset.x === "save") { const ok = onSave(form); if (ok !== false) closeDrawer(); } });
  w.addEventListener("keydown", e => { if (e.key === "Escape") closeDrawer(); });
  form.addEventListener("submit", e => e.preventDefault());
  const f = form.querySelector("input,select,textarea"); if (f) f.focus();
  return w;
}
function closeDrawer() { const d = document.getElementById("drawer"); if (d) d.remove(); }
const fv = (form, name) => { const el = form.elements[name]; if (!el) return ""; if (el.type === "checkbox") return el.checked; return (el.value || "").trim(); };
const fvAll = (form, name) => [...form.querySelectorAll(`[name="${name}"]:checked`)].map(x => x.value);
function fieldErr(form, name, msg) { const el = form.elements[name]; if (!el) return; const box = el.closest(".field"); if (!box) return; let e = box.querySelector(".err"); if (!e) { e = document.createElement("div"); e.className = "err"; box.appendChild(e); } e.textContent = msg; el.setAttribute("aria-invalid", "true"); el.focus(); }
const input = (name, label, value, opts = {}) => `<div class="field ${opts.full ? "full" : ""}"><label for="f-${name}">${esc(label)}</label>${opts.textarea ? `<textarea id="f-${name}" name="${name}">${esc(value)}</textarea>` : `<input id="f-${name}" name="${name}" type="${opts.type || "text"}" value="${esc(value)}" ${opts.step ? `step="${opts.step}"` : ""}>`}${opts.hint ? `<div class="hint">${esc(opts.hint)}</div>` : ""}</div>`;
const select = (name, label, value, options, opts = {}) => `<div class="field ${opts.full ? "full" : ""}"><label for="f-${name}">${esc(label)}</label><select id="f-${name}" name="${name}">${options.map(([v, t]) => `<option value="${esc(v)}" ${String(v) === String(value) ? "selected" : ""}>${esc(t)}</option>`).join("")}</select>${opts.hint ? `<div class="hint">${esc(opts.hint)}</div>` : ""}</div>`;
const checks = (name, label, values, options, opts = {}) => `<div class="field ${opts.full ? "full" : ""}"><label>${esc(label)}</label><div class="chips">${options.map(([v, t]) => `<label class="check tag"><input type="checkbox" name="${name}" value="${esc(v)}" ${values.includes(v) ? "checked" : ""}> ${esc(t)}</label>`).join("")}</div>${opts.hint ? `<div class="hint">${esc(opts.hint)}</div>` : ""}</div>`;
function downloadJSON(filename, obj) {
  const data = JSON.stringify(obj, null, 2);
  (async () => {
    try { const dl = window.claude && window.claude.use ? await window.claude.use("downloads") : null; if (dl) { await dl.save({ filename, data }); toast(`Exported ${filename}`); return; } } catch (e) { if (e && e.code && e.code !== "unavailable") { toast("Export cancelled", true); return; } }
    try { const a = document.createElement("a"); a.href = URL.createObjectURL(new Blob([data], { type: "application/json" })); a.download = filename; a.click(); toast(`Exported ${filename}`); } catch (e) { toast("Export is not available in this view", true); }
  })();
}

/* -------------------------------------------------------------- graphs */
function dagLayout(nodes, edges) {
  const level = {}; nodes.forEach(n => level[n] = 0);
  for (let i = 0; i < nodes.length; i++) edges.forEach(e => { if (level[e.to] < level[e.from] + 1) level[e.to] = level[e.from] + 1; });
  const cols = {}; nodes.forEach(n => (cols[level[n]] = cols[level[n]] || []).push(n));
  const pos = {}; const W = 196, H = 58, GX = 70, GY = 26;
  Object.entries(cols).forEach(([l, ns]) => ns.forEach((n, i) => pos[n] = { x: 20 + l * (W + GX), y: 20 + i * (H + GY), w: W, h: H }));
  const width = 40 + (Math.max(0, ...Object.keys(cols).map(Number)) + 1) * (W + GX) - GX; const height = 40 + Math.max(...Object.values(cols).map(c => c.length)) * (H + GY) - GY;
  return { pos, width, height };
}
function graphSVG(nodes, edges, label, opts = {}) {
  if (!nodes.length) return `<div class="empty"><b>No tasks yet</b>Derive a workflow to see it here.</div>`;
  const { pos, width, height } = dagLayout(nodes, edges);
  const e = edges.map(ed => { const a = pos[ed.from], b = pos[ed.to]; if (!a || !b) return ""; const x1 = a.x + a.w, y1 = a.y + a.h / 2, x2 = b.x, y2 = b.y + b.h / 2, mx = (x1 + x2) / 2;
    return `<path class="gedge" d="M${x1},${y1} C${mx},${y1} ${mx},${y2} ${x2 - 6},${y2}" marker-end="url(#arr)">${ed.label ? `<title>${esc(ed.label)}</title>` : ""}</path>`; }).join("");
  const n = nodes.map(id => { const p = pos[id]; const l = label(id); return `<g class="gnode ${opts.sel === id ? "sel" : ""} ${(opts.gap || []).includes(id) ? "gap" : ""}" data-node="${esc(id)}" tabindex="0" role="button" aria-label="${esc(l[0])}"><rect x="${p.x}" y="${p.y}" width="${p.w}" height="${p.h}" rx="5"/><text x="${p.x + 10}" y="${p.y + 22}">${esc(l[0].length > 28 ? l[0].slice(0, 27) + "…" : l[0])}</text><text class="t2" x="${p.x + 10}" y="${p.y + 40}">${esc(l[1] || "")}</text></g>`; }).join("");
  const ho = edges.filter(x => x.label).map(x => `<span>${esc(label(x.from)[0])} → ${esc(label(x.to)[0])}: <b>${esc(x.label)}</b></span>`).join("");
  return `<div class="graph"><svg width="${width}" height="${height}" viewBox="0 0 ${width} ${height}" role="img" aria-label="${esc(opts.aria || "Workflow graph")}"><defs><marker id="arr" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="7" markerHeight="7" orient="auto-start-reverse"><path d="M0,0 L10,5 L0,10 z" fill="currentColor" style="color:var(--faint)"/></marker></defs>${e}${n}</svg></div>${ho && !opts.noList ? `<div class="handoffs" aria-label="Hand-offs">${ho}</div>` : ""}`;
}
function barChart(series, opts = {}) {
  const W = opts.width || 560, H = opts.height || 160, pad = 28; const max = Math.max(1, ...series.map(s => s.v));
  const bw = Math.max(6, (W - pad * 2) / series.length - 6);
  const bars = series.map((s, i) => { const h = (H - pad - 18) * s.v / max; const x = pad + i * ((W - pad * 2) / series.length) + 3; return `<rect x="${x}" y="${H - pad - h}" width="${bw}" height="${h}" fill="${s.color || "var(--primary)"}" rx="2"><title>${esc(s.label)}: ${s.v}</title></rect><text x="${x + bw / 2}" y="${H - pad + 13}" text-anchor="middle">${esc(s.short || s.label)}</text>${s.v ? `<text x="${x + bw / 2}" y="${H - pad - h - 4}" text-anchor="middle">${s.v}</text>` : ""}`; }).join("");
  return `<svg class="chart" viewBox="0 0 ${W} ${H}" role="img" aria-label="${esc(opts.aria || "Chart")}"><line x1="${pad}" y1="${H - pad}" x2="${W - pad}" y2="${H - pad}" stroke="var(--rule)"/>${bars}</svg>`;
}

/* -------------------------------------------------------------- layout */
function renderShell() {
  document.getElementById("app").innerHTML = `
  <aside class="side" id="side" aria-label="Main navigation">
    <div class="brand"><svg width="28" height="28" viewBox="0 0 28 28" aria-hidden="true"><rect x="1" y="1" width="26" height="26" rx="5" fill="#0E6B6B"/><path d="M7 9h6v4H7zM15 15h6v4h-6zM13 11h3v6h-1" stroke="#fff" stroke-width="1.6" fill="none"/></svg><div><b>SelectFlow</b><small>Toolkit composition under model-controlled tool selection</small></div></div>
    <nav class="nav">${PAGES.map(([g, ps]) => `<div class="nav-group"><span>${esc(g)}</span>${ps.map(([id, t]) => `<a href="#${id}" data-nav="${id}">${icon(id)}<span>${esc(t)}</span></a>`).join("")}</div>`).join("")}</nav>
    <div class="side-foot" id="side-foot"></div>
  </aside>
  <div class="main"><header class="top"><button class="btn ghost menu-btn" id="menu" aria-label="Open navigation">☰</button><div class="crumbs" id="crumbs"></div><div class="top-right" id="topright"></div></header><main class="content" id="content" tabindex="-1"></main></div>`;
  document.getElementById("menu").addEventListener("click", () => document.getElementById("side").classList.toggle("open"));
}
function renderChrome() {
  const [g, t] = TITLES[UI.page] || ["", ""];
  document.getElementById("crumbs").innerHTML = `<span>SelectFlow</span>${g ? `<span aria-hidden="true">/</span><span>${esc(g)}</span>` : ""}<span aria-hidden="true">/</span><b>${esc(t)}</b>`;
  document.getElementById("topright").innerHTML = `<button class="btn small model-btn" data-action="open-model" data-tip="Choose the language model used for interpretation, generation and live agent calls">${icon("about", 'style="display:none"')}<span class="dot ${LLM.readySync() ? "" : "off"}"></span>${esc(LLM.label())}</button><span class="tag" data-tip="Where your changes are kept">${esc(Store.status)}</span>`;
  document.querySelectorAll("[data-nav]").forEach(a => { if (a.dataset.nav === UI.page) a.setAttribute("aria-current", "page"); else a.removeAttribute("aria-current"); });
  document.getElementById("side-foot").innerHTML = `<button class="btn small ghost" data-action="reset-demo" data-tip="Restore the registry federation and clear your changes">Reset the workspace</button>`;
}
const RENDER = {};
function render() {
  renderChrome();
  const c = document.getElementById("content");
  try { c.innerHTML = `<div class="page">${(RENDER[UI.page] || RENDER.home)()}</div>`; }
  catch (e) { console.error(e); c.innerHTML = `<div class="page"><div class="note bad">This page could not be displayed: ${esc(e.message)}</div></div>`; }
  if (AFTER[UI.page]) AFTER[UI.page]();
  initTips();
}
function initTips() { if (window.tippy) { document.querySelectorAll("[data-tip]").forEach(el => { if (el._tippy) el._tippy.setContent(el.dataset.tip); else window.tippy(el, { content: el.dataset.tip, maxWidth: 320, theme: "sf", placement: "bottom", delay: [120, 0] }); }); } else document.querySelectorAll("[data-tip]").forEach(el => el.title = el.dataset.tip); }
const AFTER = {};
const ACTIONS = {};
function route() { const h = (location.hash || "#home").slice(1); UI.page = TITLES[h] ? h : "home"; document.getElementById("side").classList.remove("open"); render(); document.getElementById("content").scrollTop = 0; }
const head = (title, lead, actions = "") => `<div class="page-head"><div class="row" style="gap:8px"><h1>${esc(title)}</h1>${lead ? `<button class="info-dot" type="button" aria-label="About this page" data-tip="${esc(String(lead).replace(/<[^>]+>/g, ""))}">i</button>` : ""}</div><div class="actions">${actions}</div></div>`;
const tip = (text) => `<button class="info-dot" type="button" aria-label="More information" data-tip="${esc(text)}">i</button>`;
const panel = (title, body, opts = {}) => `<section class="panel" ${opts.id ? `id="${opts.id}"` : ""}><div class="panel-h"><h2>${esc(title)}</h2>${opts.sub ? `<span class="sub">${opts.sub}</span>` : ""}${opts.tools ? `<div class="tools">${opts.tools}</div>` : ""}</div><div class="panel-b ${opts.flush ? "flush" : ""}">${body}</div></section>`;
const runStatus = r => ({ draft: ["info", "Draft"], interpreted: ["info", "Interpretation confirmed"], derived: ["info", "Workflow derived"], confirmed: ["info", "Workflow confirmed"], composed: ["ok", "Composed"], infeasible: ["bad", "No feasible plan"], repaired: ["warn", "Repaired"], saved: ["ok", "Plan saved"], failed: ["bad", "Derivation failed"] }[r.status] || ["info", r.status]);
const stChip = r => { const [k, t] = runStatus(r); return `<span class="st ${k}">${esc(t)}</span>`; };
const when = iso => { if (!iso) return "–"; const d = new Date(iso); return d.toLocaleString(undefined, { day: "2-digit", month: "short", hour: "2-digit", minute: "2-digit" }); };

/* ========================================================= 1 · Dashboard */
RENDER.dashboard = () => {
  const st = S(); const runs = st.runs; const ev = st.events;
  const n = { orgs: st.organizations.length, servers: st.servers.length, tools: st.tools.length, desc: st.descriptors.length, hosts: st.hosts.length, sb: st.sharingBases.length,
    prep: st.prepOps.length, req: runs.length, wf: runs.filter(r => r.derivation && r.derivation.final).length, comp: ev.filter(e => e.type === "composition" && e.details && e.details.feasible).length, rep: ev.filter(e => e.type === "repair-applied").length };
  const L = [["organizations", n.orgs, "Organizations"], ["organizations", n.servers, "MCP servers"], ["tools", n.tools, "Tools"], ["descriptors", n.desc, "Service descriptors"], ["governance", n.hosts, "Model hosts"], ["governance", n.sb, "Sharing bases"], ["preparation", n.prep, "Preparation operations"], ["history", n.req, "Requests submitted"], ["results", n.wf, "Workflows derived"], ["history", n.comp, "Successful compositions"], ["history", n.rep, "Repairs applied"]];
  const cert = { certified: st.tools.filter(t => t.certification.status === "certified").length, uncertified: st.tools.filter(t => t.certification.status === "uncertified").length, rejected: st.tools.filter(t => t.certification.status === "rejected").length };
  const noCard = st.tools.filter(t => !t.card).length;
  const recentReq = runs.slice(-6).reverse();
  const compEv = ev.filter(e => ["composition", "repair-applied", "plan-saved"].includes(e.type)).slice(-6).reverse();
  const catEv = ev.filter(e => /^(prep|tool|org|server|desc|sharing|config)/.test(e.type)).slice(-6).reverse();
  const orgAct = st.organizations.map(o => ({ o, tools: st.tools.filter(t => t.orgId === o.id).length, desc: st.descriptors.filter(d => d.orgId === o.id).length, tasks: runs.reduce((s, r) => s + ((r.derivation && r.derivation.final) || []).filter(id => (byId(st.descriptors, id) || {}).orgId === o.id).length, 0) }));
  return head("Dashboard", "Operational overview of this SelectFlow environment. Every number comes from the current configuration or from activity in this portal.", `<a class="btn primary" href="#workspace">New request</a><a class="btn" href="#preparation">Prepare the catalogue</a>`) +
    `<div class="row" style="margin-bottom:8px">${prov("observed", "Counts computed from this portal")}<span class="muted small">The demonstration federation is illustrative; requests and operations are the ones made here.</span></div>` +
    `<div class="ledger" style="margin-bottom:16px">${L.map(([p, v, k]) => `<div><a href="#${p}"><div class="v">${v}</div><div class="k">${esc(k)}</div></a></div>`).join("")}</div>` +
    `<div class="grid g2">` +
    panel("Recent requests", recentReq.length ? `<div class="tbl-wrap"><table class="tbl"><thead><tr><th>Request</th><th>Status</th><th>When</th></tr></thead><tbody>${recentReq.map(r => `<tr class="click" data-action="open-run" data-id="${r.id}"><td>${esc(r.request.text.slice(0, 70))}</td><td>${stChip(r)}</td><td class="muted">${when(r.createdAt)}</td></tr>`).join("")}</tbody></table></div>` : `<div class="empty"><b>No request yet</b>Submit one in the workflow workspace to see it here.<br><a class="btn small" style="margin-top:8px" href="#workspace">Open the workspace</a></div>`, { flush: true }) +
    panel("Recent composition activity", compEv.length ? `<div class="tbl-wrap"><table class="tbl"><tbody>${compEv.map(e => `<tr${e.runId ? ` class="click" data-action="open-run" data-id="${e.runId}"` : ""}><td>${esc(e.summary)}</td><td class="muted">${when(e.t)}</td></tr>`).join("")}</tbody></table></div>` : `<div class="empty"><b>No composition yet</b>Compositions appear once a workflow has been confirmed.</div>`, { flush: true }) +
    panel("Recent catalogue updates", catEv.length ? `<div class="tbl-wrap"><table class="tbl"><tbody>${catEv.map(e => `<tr><td>${esc(e.summary)}</td><td class="muted">${when(e.t)}</td></tr>`).join("")}</tbody></table></div>` : `<div class="empty"><b>No update yet</b>Changes to organizations, tools, descriptors and policies are listed here.</div>`, { flush: true }) +
    panel("Certification status", `<dl class="kv"><dt>Certified</dt><dd>${cert.certified} ${prov("simulated", "Simulated decision")}</dd><dt>Not certified</dt><dd>${cert.uncertified}</dd><dt>Rejected by audit</dt><dd>${cert.rejected}</dd><dt>Without tool card</dt><dd>${noCard}${noCard ? ` <span class="muted small">(cannot be offered to an agent)</span>` : ""}</dd></dl><div class="bar" style="margin-top:12px" aria-hidden="true"><i style="width:${100 * cert.certified / Math.max(1, st.tools.length)}%"></i></div><p class="small muted" style="margin-top:8px">Uncertified tools are treated pessimistically by the composer: they may return any data and, for third parties, forward it.</p><a class="btn small" href="#preparation">Open certification</a>`) +
    panel("Organization activity", `<div class="tbl-wrap"><table class="tbl"><thead><tr><th>Organization</th><th class="num">Tools</th><th class="num">Descriptors</th><th class="num">Tasks in portal workflows</th></tr></thead><tbody>${orgAct.map(x => `<tr class="click" data-action="goto-org" data-id="${x.o.id}"><td>${esc(x.o.name)}</td><td class="num">${x.tools}</td><td class="num">${x.desc}</td><td class="num">${x.tasks}</td></tr>`).join("")}</tbody></table></div>`, { flush: true }) +
    panel("System status", `<dl class="kv"><dt>Persistence</dt><dd>${esc(Store.status)}</dd><dt>MCP servers</dt><dd>${st.servers.filter(s => s.status === "simulated").length} simulated, ${st.servers.filter(s => s.status === "disabled").length} disabled ${prov("simulated")}</dd><dt>Model hosts</dt><dd>${st.hosts.map(h => esc(h.name) + " (" + esc(h.model.mode.replace("-", " ")) + ")").join("<br>")}</dd><dt>Language model</dt><dd>Simulated; live interpretation can be requested in step 2 when this view allows it.</dd><dt>Last change</dt><dd>${when(st.updatedAt)}</dd></dl>`) +
    `</div>`;
};

/* ============================================== 2 · Environment configuration */
RENDER.environment = () => {
  const st = S(); const c = st.config; const p = c.params; const tab = UI.envTab;
  const tabs = [["domain", "Domain"], ["vocabulary", "Artefacts"], ["capabilities", "Capabilities"], ["categories", "Categories and purposes"], ["parameters", "Parameters"]];
  let body = "";
  if (tab === "domain") body = panel("Domain", `<form id="env-domain">${input("domain", "Domain name", c.domain)}${input("description", "Description", c.description, { textarea: true })}<div class="row"><button class="btn primary" data-action="save-domain">Save domain</button></div></form>`);
  if (tab === "vocabulary") body = panel("Artefact types", `<div class="tbl-wrap"><table class="tbl"><thead><tr><th>Identifier</th><th>Name</th><th>Data categories</th><th>Usually held by requesters</th><th></th></tr></thead><tbody>${c.artefacts.map(a => `<tr><td><code>${esc(a.id)}</code></td><td>${esc(a.name)}</td><td>${a.categories.map(x => `<span class="tag">${esc(x)}</span>`).join("")}</td><td>${a.usuallyHeld ? "Yes" : "No"}</td><td class="num"><button class="btn small" data-action="edit-artefact" data-id="${esc(a.id)}">Edit</button> <button class="btn small danger" data-action="del-artefact" data-id="${esc(a.id)}">Delete</button></td></tr>`).join("")}</tbody></table></div>`, { flush: true, tools: `<button class="btn small primary" data-action="edit-artefact">Add artefact</button>`, sub: "Documents exchanged between tasks" });
  if (tab === "capabilities") body = panel("Capability taxonomy", `<div class="tbl-wrap"><table class="tbl"><thead><tr><th>Identifier</th><th>Name</th><th>Kind of step</th><th>Statement given to the agent</th><th></th></tr></thead><tbody>${c.capabilities.map(a => `<tr><td><code>${esc(a.id)}</code></td><td>${esc(a.name)}</td><td>${esc(a.category)}</td><td class="muted">${esc(a.statement)}</td><td class="num"><button class="btn small" data-action="edit-capability" data-id="${esc(a.id)}">Edit</button> <button class="btn small danger" data-action="del-capability" data-id="${esc(a.id)}">Delete</button></td></tr>`).join("")}</tbody></table></div>`, { flush: true, tools: `<button class="btn small primary" data-action="edit-capability">Add capability</button>` });
  if (tab === "categories") body = `<div class="grid g3">${panel("Data categories", `<form id="env-cats">${input("cats", "Categories (code: name, one per line)", c.dataCategories.map(x => x.id + ": " + x.name).join("\n"), { textarea: true, hint: "Used by sharing bases and flow checks." })}<button class="btn primary" data-action="save-cats">Save categories</button></form>`)}${panel("Purposes", `<form id="env-purp">${input("purposes", "Purposes (one per line)", c.purposes.join("\n"), { textarea: true, hint: "Every descriptor has one purpose; sharing rules refer to it." })}<button class="btn primary" data-action="save-purposes">Save purposes</button></form>`)}${panel("Task categories", `<form id="env-task">${input("tasks", "Kinds of step (one per line)", c.taskCategories.join("\n"), { textarea: true })}<button class="btn primary" data-action="save-taskcats">Save task categories</button></form>`)}</div>`;
  if (tab === "parameters") body = `<form id="env-params" class="grid g2">${panel("Workflow derivation", `<div class="form-grid">${input("nRetrieve", "Descriptors retrieved", p.nRetrieve, { type: "number", hint: "Passed to the workflow generator" })}${input("kCandidates", "Candidate workflows", p.kCandidates, { type: "number" })}${input("nRevisions", "Revisions per candidate", p.nRevisions, { type: "number" })}${input("tauChi", "Alignment confidence threshold τχ", p.tauChi, { type: "number", step: "0.05", hint: "Hand-offs below it are rejected by the alignment critic" })}</div>`)}${panel("Toolkit composition", `<div class="form-grid">${input("kMax", "Maximum tools per toolkit", p.kMax, { type: "number", hint: "Constraint C4" })}${input("N", "Candidate tools per task", p.N, { type: "number" })}${input("nMin", "Tools required per capability", p.nMin, { type: "number", hint: "Coverage, constraint C1" })}${input("tauMu", "Mapping confidence threshold τμ", p.tauMu, { type: "number", step: "0.05" })}${input("wrongCost", "Cost of a wrong call ψ", p.wrongCost, { type: "number", step: "0.05" })}${input("lambdaQ", "Weight of quality in the plan choice λ", p.lambdaQ, { type: "number", step: "0.05" })}</div>`)}${panel("Quality-of-service thresholds (C6)", `<div class="form-grid">${input("maxDurationDays", "Maximum duration (days)", c.qos.maxDurationDays, { type: "number" })}${input("maxPrice", "Maximum price (€)", c.qos.maxPrice, { type: "number" })}${input("minDependability", "Minimum dependability", c.qos.minDependability, { type: "number", step: "0.01" })}</div>`)}${panel("Certification and repair", `<div class="form-grid">${input("eps", "Target false-certification rate ε", p.eps, { type: "number", step: "0.01" })}${input("auditFraction", "Share of tools audited", p.auditFraction, { type: "number", step: "0.05" })}${["requester", "alternative", "budget", "sharing", "certify"].map(k => input("w_" + k, "Repair weight: " + { requester: "leave to requester", alternative: "alternative descriptor", budget: "raise a budget", sharing: "new sharing base", certify: "certify a tool" }[k], p.repairWeights[k], { type: "number" })).join("")}</div>`)}<div class="row" style="grid-column:1/-1"><button class="btn primary" data-action="save-params">Save parameters</button><span class="muted small">Changes apply to the next derivation and composition.</span></div></form>`;
  return head("Environment configuration", "Domain vocabulary, capability taxonomy and the parameters used by derivation, composition, certification and repair.") +
    `<div class="tabs" role="tablist">${tabs.map(([id, t]) => `<button role="tab" aria-selected="${tab === id}" data-action="env-tab" data-id="${id}">${esc(t)}</button>`).join("")}</div>` + `<div class="row" style="margin-bottom:10px">${prov("configured")}</div>` + body;
};
ACTIONS["env-tab"] = el => { UI.envTab = el.dataset.id; render(); };
ACTIONS["save-domain"] = () => { const f = document.getElementById("env-domain"); const d = fv(f, "domain"); if (!d) return fieldErr(f, "domain", "Enter a domain name."); Store.commit(s => { s.config.domain = d; s.config.description = fv(f, "description"); Store.log("config", "Domain description updated"); }); toast("Domain saved"); };
ACTIONS["save-cats"] = () => { const f = document.getElementById("env-cats"); const rows = fv(f, "cats").split("\n").map(x => x.trim()).filter(Boolean).map(x => { const [id, ...n] = x.split(":"); return { id: id.trim().toUpperCase(), name: n.join(":").trim() || id.trim() }; }); if (!rows.length) return fieldErr(f, "cats", "Keep at least one category."); Store.commit(s => { s.config.dataCategories = rows; Store.log("config", "Data categories updated"); }); toast("Categories saved"); };
ACTIONS["save-purposes"] = () => { const f = document.getElementById("env-purp"); const rows = fv(f, "purposes").split("\n").map(x => x.trim()).filter(Boolean); if (!rows.length) return fieldErr(f, "purposes", "Keep at least one purpose."); Store.commit(s => { s.config.purposes = rows; Store.log("config", "Purposes updated"); }); toast("Purposes saved"); };
ACTIONS["save-taskcats"] = () => { const f = document.getElementById("env-task"); const rows = fv(f, "tasks").split("\n").map(x => x.trim()).filter(Boolean); Store.commit(s => { s.config.taskCategories = rows; Store.log("config", "Task categories updated"); }); toast("Task categories saved"); };
ACTIONS["save-params"] = () => {
  const f = document.getElementById("env-params"); const num = n => Number(fv(f, n));
  const checks = [["kMax", 1, 8], ["N", 1, 12], ["nMin", 1, 4], ["tauMu", 0, 1], ["tauChi", 0, 1], ["wrongCost", 0, 2], ["lambdaQ", 0, 1], ["nRetrieve", 1, 20], ["kCandidates", 1, 5], ["nRevisions", 0, 5], ["eps", 0.01, 0.5], ["auditFraction", 0.05, 0.9], ["maxDurationDays", 1, 365], ["maxPrice", 0, 100000], ["minDependability", 0, 1]];
  for (const [n, lo, hi] of checks) { const v = num(n); if (isNaN(v) || v < lo || v > hi) return fieldErr(f, n, `Enter a value between ${lo} and ${hi}.`); }
  Store.commit(s => { const p = s.config.params; ["kMax", "N", "nMin", "nRetrieve", "kCandidates", "nRevisions"].forEach(k => p[k] = Math.round(num(k))); ["tauMu", "tauChi", "wrongCost", "lambdaQ", "eps", "auditFraction"].forEach(k => p[k] = num(k)); ["requester", "alternative", "budget", "sharing", "certify"].forEach(k => p.repairWeights[k] = num("w_" + k) || 1); s.config.qos = { maxDurationDays: num("maxDurationDays"), maxPrice: num("maxPrice"), minDependability: num("minDependability") }; Store.log("config", "Parameters updated", null, clone(p)); });
  toast("Parameters saved");
};
ACTIONS["edit-artefact"] = el => {
  const st = S(); const a = el.dataset.id ? byId(st.config.artefacts, el.dataset.id) : { id: "", name: "", categories: [], usuallyHeld: false };
  openDrawer(el.dataset.id ? "Edit artefact" : "Add artefact", `${input("id", "Identifier", a.id, { hint: "Lower case, underscores; cannot be changed later" })}${input("name", "Name", a.name)}${checks("cats", "Data categories", a.categories, st.config.dataCategories.map(c => [c.id, c.name]))}<label class="check"><input type="checkbox" name="held" ${a.usuallyHeld ? "checked" : ""}> Usually held by requesters</label>`, form => {
    const id = fv(form, "id").toLowerCase().replace(/[^a-z0-9_]/g, "_"); if (!id) { fieldErr(form, "id", "Enter an identifier."); return false; }
    if (!el.dataset.id && byId(st.config.artefacts, id)) { fieldErr(form, "id", "This identifier already exists."); return false; }
    if (!fv(form, "name")) { fieldErr(form, "name", "Enter a name."); return false; }
    Store.commit(s => { const x = { id: el.dataset.id || id, name: fv(form, "name"), categories: fvAll(form, "cats"), usuallyHeld: fv(form, "held") }; const i = s.config.artefacts.findIndex(y => y.id === x.id); if (i >= 0) s.config.artefacts[i] = x; else s.config.artefacts.push(x); Store.log("config", `Artefact ${x.id} saved`); }); toast("Artefact saved");
  });
  if (el.dataset.id) document.querySelector('#drawer [name="id"]').readOnly = true;
};
ACTIONS["del-artefact"] = el => { const id = el.dataset.id; const used = S().descriptors.some(d => d.requires.includes(id) || d.delivers.includes(id)) || S().tools.some(t => t.inputArtefacts.includes(id) || t.outputArtefacts.includes(id)); if (used) return toast("This artefact is used by descriptors or tools; remove those references first.", true); confirmDialog(`Delete the artefact ${id}?`, "Delete artefact", () => { Store.commit(s => { s.config.artefacts = s.config.artefacts.filter(a => a.id !== id); Store.log("config", `Artefact ${id} deleted`); }); toast("Artefact deleted"); }); };
ACTIONS["edit-capability"] = el => {
  const st = S(); const a = el.dataset.id ? byId(st.config.capabilities, el.dataset.id) : { id: "", name: "", category: st.config.taskCategories[0], statement: "" };
  openDrawer(el.dataset.id ? "Edit capability" : "Add capability", `${input("id", "Identifier", a.id, { hint: "For example cap-site-submit" })}${input("name", "Name", a.name)}${select("category", "Kind of step", a.category, st.config.taskCategories.map(x => [x, x]))}${input("statement", "Statement given to the agent", a.statement, { textarea: true, hint: "Written as the step the agent must perform." })}`, form => {
    const id = fv(form, "id"); if (!id) { fieldErr(form, "id", "Enter an identifier."); return false; } if (!el.dataset.id && byId(st.config.capabilities, id)) { fieldErr(form, "id", "This identifier already exists."); return false; }
    if (!fv(form, "statement")) { fieldErr(form, "statement", "Enter the statement."); return false; }
    Store.commit(s => { const x = { id: el.dataset.id || id, name: fv(form, "name") || id, category: fv(form, "category"), statement: fv(form, "statement") }; const i = s.config.capabilities.findIndex(y => y.id === x.id); if (i >= 0) s.config.capabilities[i] = x; else s.config.capabilities.push(x); Store.log("config", `Capability ${x.id} saved`); }); toast("Capability saved");
  });
  if (el.dataset.id) document.querySelector('#drawer [name="id"]').readOnly = true;
};
ACTIONS["del-capability"] = el => { const id = el.dataset.id; if (S().descriptors.some(d => d.capabilities.includes(id))) return toast("A descriptor requires this capability; edit the descriptor first.", true); confirmDialog(`Delete the capability ${id}?`, "Delete capability", () => { Store.commit(s => { s.config.capabilities = s.config.capabilities.filter(a => a.id !== id); s.tools.forEach(t => { if (t.card) delete t.card.caps[id]; }); Store.log("config", `Capability ${id} deleted`); }); toast("Capability deleted"); }); };

/* ========================================= 3 · Organizations and MCP servers */
RENDER.organizations = () => {
  const st = S(); const sel = byId(st.organizations, UI.selOrg) || st.organizations[0];
  const list = `<div class="tbl-wrap"><table class="tbl"><thead><tr><th>Organization</th><th>Category</th><th class="num">Servers</th><th class="num">Tools</th><th>Status</th></tr></thead><tbody>${st.organizations.map(o => `<tr class="click ${sel && sel.id === o.id ? "sel" : ""}" data-action="sel-org" data-id="${o.id}" tabindex="0"><td>${esc(o.name)}${o.country && o.country !== "Both" ? " " + countryTag(o.country) : ""}</td><td>${esc(o.category)}</td><td class="num">${st.servers.filter(s => s.orgId === o.id).length}</td><td class="num">${st.tools.filter(t => t.orgId === o.id).length}</td><td><span class="st ${o.status === "active" ? "ok" : "warn"}">${esc(o.status)}</span></td></tr>`).join("")}</tbody></table></div>`;
  let detail = `<div class="empty"><b>No organization</b>Register the first one.</div>`;
  if (sel) {
    const servers = st.servers.filter(s => s.orgId === sel.id); const tools = st.tools.filter(t => t.orgId === sel.id); const desc = st.descriptors.filter(d => d.orgId === sel.id);
    const caps = [...new Set(desc.flatMap(d => d.capabilities))]; const sbs = st.sharingBases.filter(b => b.orgIds.includes(sel.id) || b.rules.some(r => r.receiver === sel.id || r.origin === sel.id));
    detail = panel(sel.name, `<dl class="kv"><dt>Identifier</dt><dd><code>${esc(sel.id)}</code></dd><dt>Category</dt><dd>${esc(sel.category)}</dd><dt>Status</dt><dd>${esc(sel.status)}</dd><dt>Description</dt><dd>${esc(sel.description)}</dd><dt>Declared capabilities</dt><dd>${caps.length ? caps.map(c => `<span class="tag">${esc(capById(c).name)}</span>`).join("") : '<span class="muted">None</span>'} ${caps.length ? prov("declared") : ""}</dd><dt>Sharing agreements</dt><dd>${sbs.length ? sbs.map(b => `<span class="tag">${esc(b.name)}</span>`).join("") : '<span class="muted">None</span>'}</dd></dl>`, { tools: `<button class="btn small" data-action="edit-org" data-id="${sel.id}">Edit</button><button class="btn small danger" data-action="del-org" data-id="${sel.id}">Delete</button>` }) +
      panel("MCP servers", servers.length ? `<div class="tbl-wrap"><table class="tbl"><thead><tr><th>Server</th><th>Endpoint</th><th>Status</th><th class="num">Tools</th><th class="num">Preamble</th><th></th></tr></thead><tbody>${servers.map(s => `<tr><td>${esc(s.name)}</td><td><code>${esc(s.endpoint)}</code></td><td>${s.status === "connected" ? prov("live", "Connected") : `<span class="tag" data-tip="Procedure server built from an official registry; calls are executed by the portal's procedure runtime">Registry</span>`}</td><td class="num">${st.tools.filter(t => t.serverId === s.id).length}</td><td class="num">${s.preambleTokens} tokens</td><td class="num"><button class="btn small" data-action="edit-server" data-id="${s.id}">Edit</button> <button class="btn small danger" data-action="del-server" data-id="${s.id}">Delete</button></td></tr>`).join("")}</tbody></table></div>` : `<div class="empty"><b>No server</b>Add the MCP server that publishes this organization’s tools.</div>`, { flush: true, tools: `<button class="btn small primary" data-action="edit-server" data-org="${sel.id}">Add server</button>` }) +
      panel("Tools and descriptors", `<div class="grid g2"><div><h3>Tools (${tools.length})</h3>${tools.map(t => `<div class="listrow"><a href="#tools" data-action="open-tool" data-id="${esc(t.id)}" data-tip="${esc(t.id)}">${toolGlyph(t.kind, 13)} ${esc(t.name)}</a>${certChip(t)}</div>`).join("") || '<p class="muted">None</p>'}</div><div><h3>Service descriptors (${desc.length})</h3>${desc.map(d => `<div class="listrow"><a href="#descriptors" data-action="open-desc" data-id="${d.id}">${esc(d.name)}</a></div>`).join("") || '<p class="muted">None</p>'}</div></div>`);
  }
  return head("Organizations and MCP servers", "The federation: who publishes which MCP servers, tools and service descriptors.", `<button class="btn primary" data-action="edit-org">Register organization</button>`) +
    `<div class="grid" style="grid-template-columns:minmax(0,5fr) minmax(0,7fr)">${panel("Organizations", list, { flush: true, sub: `${st.organizations.length} registered` })}<div class="stack">${detail}</div></div>`;
};
ACTIONS["sel-org"] = el => { UI.selOrg = el.dataset.id; render(); };
ACTIONS["goto-org"] = el => { UI.selOrg = el.dataset.id; location.hash = "organizations"; };
ACTIONS["edit-org"] = el => {
  const st = S(); const o = el.dataset.id ? byId(st.organizations, el.dataset.id) : { id: "", name: "", category: "Public agency", description: "", status: "active" };
  const cats = [...new Set(["Municipality", "Ministry", "Public agency", "Third-party provider"].concat(st.organizations.map(x => x.category)))];
  openDrawer(el.dataset.id ? "Edit organization" : "Register organization", `${input("name", "Name", o.name)}${select("category", "Category", o.category, cats.map(c => [c, c]))}${input("newcat", "Or a new category", "", { hint: "Leave empty to keep the category above" })}${input("description", "Description", o.description, { textarea: true })}${select("status", "Operational status", o.status, [["active", "Active"], ["suspended", "Suspended"]])}`, form => {
    if (!fv(form, "name")) { fieldErr(form, "name", "Enter a name."); return false; }
    Store.commit(s => { const x = { ...o, name: fv(form, "name"), category: fv(form, "newcat") || fv(form, "category"), description: fv(form, "description"), status: fv(form, "status"), demo: false }; if (!x.id) { x.id = uid("org"); x.createdAt = new Date().toISOString(); s.organizations.push(x); } else Object.assign(byId(s.organizations, x.id), x); UI.selOrg = x.id; Store.log("org", `Organization ${x.name} saved`); }); toast("Organization saved");
  });
};
ACTIONS["del-org"] = el => { const id = el.dataset.id; const st = S(); if (st.hosts.some(h => h.operatorOrgId === id)) return toast("This organization operates a model host; reassign the host first.", true); const nT = st.tools.filter(t => t.orgId === id).length, nD = st.descriptors.filter(d => d.orgId === id).length;
  confirmDialog(`Delete ${orgName(id)} with its ${st.servers.filter(s => s.orgId === id).length} server(s), ${nT} tool(s) and ${nD} descriptor(s)?`, "Delete organization", () => { Store.commit(s => { const name = orgName(id); s.organizations = s.organizations.filter(o => o.id !== id); s.servers = s.servers.filter(x => x.orgId !== id); s.tools = s.tools.filter(t => t.orgId !== id); s.descriptors = s.descriptors.filter(d => d.orgId !== id); s.descriptors.forEach(d => d.companions = d.companions.filter(c => byId(s.descriptors, c))); s.sharingBases.forEach(b => { b.orgIds = b.orgIds.filter(x => x !== id); b.rules = b.rules.filter(r => r.origin !== id && r.receiver !== id); }); UI.selOrg = null; Store.log("org", `Organization ${name} deleted`); }); toast("Organization deleted"); }); };
ACTIONS["edit-server"] = el => {
  const st = S(); const s0 = el.dataset.id ? byId(st.servers, el.dataset.id) : { id: "", orgId: el.dataset.org, name: "", endpoint: "sim://", status: "simulated", preambleTokens: 120 };
  openDrawer(el.dataset.id ? "Edit MCP server" : "Add MCP server", `${select("orgId", "Publishing organization", s0.orgId, st.organizations.map(o => [o.id, o.name]))}${input("name", "Server name", s0.name)}${input("endpoint", "Endpoint", s0.endpoint, { hint: "Only sim:// endpoints are served by the simulation backend; other schemes are recorded but never contacted." })}${select("status", "Status", s0.status, [["simulated", "Simulated"], ["disabled", "Disabled"]])}${input("preamble", "Server preamble (tokens loaded with any of its tools)", s0.preambleTokens, { type: "number" })}`, form => {
    if (!fv(form, "name")) { fieldErr(form, "name", "Enter a server name."); return false; } const ep = fv(form, "endpoint"); if (!/^[a-z]+:\/\/\S+/.test(ep)) { fieldErr(form, "endpoint", "Enter an endpoint such as sim://example.gov/mcp."); return false; }
    const pre = Number(fv(form, "preamble")); if (isNaN(pre) || pre < 0) { fieldErr(form, "preamble", "Enter a number of tokens."); return false; }
    Store.commit(s => { const x = { ...s0, orgId: fv(form, "orgId"), name: fv(form, "name"), endpoint: ep, status: fv(form, "status"), preambleTokens: pre, demo: false }; if (!x.id) { x.id = uid("srv"); s.servers.push(x); } else { Object.assign(byId(s.servers, x.id), x); s.tools.filter(t => t.serverId === x.id).forEach(t => t.orgId = x.orgId); } Store.log("server", `MCP server ${x.name} saved`); }); toast("Server saved");
  });
};
ACTIONS["del-server"] = el => { const id = el.dataset.id; const n = S().tools.filter(t => t.serverId === id).length; confirmDialog(`Delete this server and its ${n} tool(s)?`, "Delete server", () => { Store.commit(s => { s.servers = s.servers.filter(x => x.id !== id); s.tools = s.tools.filter(t => t.serverId !== id); Store.log("server", `MCP server ${id} deleted`); }); toast("Server deleted"); }); };

/* ============================================================ 4 · Tools */
function filteredTools() {
  const st = S(); const f = UI.toolFilter; const q = f.q.toLowerCase();
  let ts = st.tools.filter(t => (!q || (t.id + " " + t.name + " " + t.description).toLowerCase().includes(q)) && (!f.org || t.orgId === f.org) && (!f.cap || (t.card && (t.card.caps[f.cap] || 0) > 0)) && (!f.cert || t.certification.status === f.cert || (f.cert === "nocard" && !t.card)) && (!f.maxLatency || t.qos.latencyS <= Number(f.maxLatency)) && (!f.minDep || t.qos.dependability >= Number(f.minDep)));
  const key = { name: t => t.name, org: t => orgName(t.orgId), tokens: t => t.tokens, latency: t => t.qos.latencyS, price: t => t.qos.price, dep: t => t.qos.dependability, cert: t => t.certification.status }[f.sort] || (t => t.name);
  return ts.sort((a, b) => (key(a) > key(b) ? 1 : key(a) < key(b) ? -1 : 0) * f.dir);
}
RENDER.tools = () => {
  const st = S(); const f = UI.toolFilter; const ts = filteredTools();
  const th = (k, t, cls = "") => `<th class="sortable ${cls}" data-action="sort-tools" data-id="${k}" aria-sort="${f.sort === k ? (f.dir > 0 ? "ascending" : "descending") : "none"}">${esc(t)}${f.sort === k ? (f.dir > 0 ? " ▲" : " ▼") : ""}</th>`;
  return head("Tools catalog", "Every model-invocable operation published by the federation, with its tool card. Cards come from the preparation phase and feed derivation and composition.", `<button class="btn primary" data-action="edit-tool">Add tool</button><button class="btn" data-action="export-tools">Export</button><label class="btn" tabindex="0">Import<input type="file" accept="application/json" data-action-change="import-tools" class="sr"></label>`) +
    `<section class="panel"><div class="panel-h" style="flex-wrap:wrap;gap:8px"><input type="text" placeholder="Search tools" aria-label="Search tools" value="${esc(f.q)}" data-filter="tool.q" style="max-width:240px">
      <select aria-label="Organization" data-filter="tool.org" style="max-width:200px"><option value="">All organizations</option>${st.organizations.map(o => `<option value="${o.id}" ${f.org === o.id ? "selected" : ""}>${esc(o.name)}</option>`).join("")}</select>
      <select aria-label="Capability" data-filter="tool.cap" style="max-width:220px"><option value="">All capabilities</option>${st.config.capabilities.map(c => `<option value="${c.id}" ${f.cap === c.id ? "selected" : ""}>${esc(c.name)}</option>`).join("")}</select>
      <select aria-label="Certification" data-filter="tool.cert" style="max-width:170px"><option value="">Any certification</option>${[["certified", "Certified"], ["uncertified", "Not certified"], ["rejected", "Rejected"], ["nocard", "Without card"]].map(([v, t]) => `<option value="${v}" ${f.cert === v ? "selected" : ""}>${t}</option>`).join("")}</select>
      <input type="number" placeholder="Max latency (s)" aria-label="Maximum latency in seconds" value="${esc(f.maxLatency)}" data-filter="tool.maxLatency" style="max-width:140px" step="0.1">
      <input type="number" placeholder="Min dependability" aria-label="Minimum dependability" value="${esc(f.minDep)}" data-filter="tool.minDep" style="max-width:150px" step="0.01">
      <span class="sub">${ts.length} of ${st.tools.length}</span></div>
      <div class="tbl-wrap"><table class="tbl"><thead><tr>${th("name", "Tool")}${th("org", "Organization")}<th>Capabilities (card)</th>${th("tokens", "Tokens", "num")}${th("latency", "Latency", "num")}${th("price", "Price", "num")}${th("dep", "Depend.", "num")}${th("cert", "Certification")}</tr></thead><tbody>${ts.map(t => `<tr class="click" data-action="open-tool" data-id="${esc(t.id)}" tabindex="0"><td><b>${esc(t.name)}</b><br><code class="muted">${esc(t.id)}</code></td><td>${esc(orgName(t.orgId))}</td><td>${t.card ? Object.entries(t.card.caps).map(([c, m]) => `<span class="tag" title="Mapping confidence">${esc(capById(c).name)} · ${fmt(m)}</span>`).join("") || '<span class="muted small">No capability found</span>' : `<span class="st warn">No tool card</span>`}</td><td class="num">${t.tokens}</td><td class="num">${fmt(t.qos.latencyS, 1)} s</td><td class="num">${fmt(t.qos.price, 0)} €</td><td class="num">${fmt(t.qos.dependability, 3)}</td><td>${certChip(t)}</td></tr>`).join("") || `<tr><td colspan="8"><div class="empty"><b>No tool matches these filters</b>Clear a filter or add a tool.</div></td></tr>`}</tbody></table></div></section>`;
};
ACTIONS["sort-tools"] = el => { const f = UI.toolFilter; if (f.sort === el.dataset.id) f.dir *= -1; else { f.sort = el.dataset.id; f.dir = 1; } render(); };
ACTIONS["export-tools"] = () => downloadJSON("selectflow-tools.json", { exportedAt: new Date().toISOString(), note: "Illustrative demonstration catalogue", tools: S().tools });
ACTIONS["import-tools"] = el => { const file = el.files[0]; if (!file) return; file.text().then(txt => { let data; try { data = JSON.parse(txt); } catch (e) { return toast("The file is not valid JSON.", true); } const list = Array.isArray(data) ? data : data.tools; if (!Array.isArray(list)) return toast("Expected a list of tools.", true); const st = S(); let added = 0, skipped = 0;
  Store.commit(s => { list.forEach(t => { if (!t || !t.id || !t.serverId || !byId(s.servers, t.serverId) || byId(s.tools, t.id)) { skipped++; return; } const srv = byId(s.servers, t.serverId); s.tools.push({ id: String(t.id), serverId: srv.id, orgId: srv.orgId, name: String(t.name || t.id), description: String(t.description || ""), inputArtefacts: t.inputArtefacts || [], outputArtefacts: t.outputArtefacts || [], inputCategories: t.inputCategories || ["ID"], inputSchema: t.inputSchema || { type: "object" }, outputSchema: t.outputSchema || { type: "object" }, tokens: Number(t.tokens) || 200, qos: t.qos || { latencyS: 1, price: 0, dependability: 0.98 }, declared: t.declared || { forwards: false, retains: [], attested: false }, truth: t.declared || { forwards: false, retains: [] }, card: null, certification: { status: "uncertified", score: null, audited: false, attested: false, history: [] }, demo: false }); added++; }); Store.log("tool", `Imported ${added} tool(s)`); });
  toast(`${added} tool(s) imported${skipped ? `, ${skipped} skipped (unknown server or duplicate id)` : ""}`); }); };
function toolDetail(t) {
  const st = S(); const c = t.card; const cert = t.certification;
  return `<dl class="kv"><dt>Identifier</dt><dd><code>${esc(t.id)}</code></dd><dt>Organization</dt><dd>${esc(orgName(t.orgId))}</dd><dt>MCP server</dt><dd>${esc((serverOf(t) || {}).name)}</dd><dt>Description</dt><dd>${esc(t.description)} ${prov("declared")}</dd><dt>Input artefacts</dt><dd>${t.inputArtefacts.map(a => `<span class="tag">${esc(artName(a))}</span>`).join("") || "–"}</dd><dt>Output artefacts</dt><dd>${t.outputArtefacts.map(a => `<span class="tag">${esc(artName(a))}</span>`).join("") || "–"}</dd><dt>Data it receives</dt><dd>${t.inputCategories.map(x => `<span class="tag">${esc(x)}</span>`).join("")}</dd><dt>Context cost</dt><dd>${t.tokens} tokens (+ ${(serverOf(t) || {}).preambleTokens || 0} server preamble)</dd><dt>QoS</dt><dd>${fmt(t.qos.latencyS, 1)} s · ${fmt(t.qos.price, 0)} € · dependability ${fmt(t.qos.dependability, 3)} ${prov("declared")}</dd><dt>Declared behaviour</dt><dd>${t.declared.forwards ? "Forwards data" : "Does not forward data"}; returns ${t.declared.retains.length ? t.declared.retains.join(", ") : "no personal data"} ${t.declared.attested ? prov("declared", "Provider attestation") : '<span class="muted small">no attestation</span>'}</dd><dt>Certification</dt><dd>${certChip(t)}${cert.score != null ? ` <span class="muted small">score ${fmt(cert.score)}${cert.pvalue != null ? `, p-value ${fmt(cert.pvalue, 3)}` : ""}${cert.at ? `, ε = ${cert.eps}` : ""}</span>` : ""}</dd></dl>` +
    `<h3 style="margin-top:16px">Tool card</h3>${c ? `<p class="small">${c.provenance === "registry" ? `<span class="tag" data-tip="Derived from the registry: the tool belongs to this procedure">Registry-derived</span>` : c.provenance === "live" ? prov("live", c.model || "Live model") : prov("simulated", "Simulated mapping")} ${c.status === "accepted" ? prov("configured", "Accepted by a user") : '<span class="muted small">Generated, not yet accepted</span>'} </p><table class="tbl"><thead><tr><th>Capability</th><th class="num">Mapping confidence μ</th><th></th></tr></thead><tbody>${Object.entries(c.caps).map(([r, m]) => `<tr><td>${esc(capById(r).name)}</td><td class="num">${fmt(m)}</td><td style="width:120px"><div class="bar sim"><i style="width:${m * 100}%"></i></div></td></tr>`).join("") || '<tr><td colspan="3" class="muted">The mapping found no capability.</td></tr>'}</tbody></table>` : `<div class="note">No card yet: map it in the preparation center before it can be offered.</div>`}` +
    `<h3 style="margin-top:16px">Input schema</h3><pre class="code">${esc(JSON.stringify(t.inputSchema, null, 2))}</pre><h3 style="margin-top:12px">Output schema</h3><pre class="code">${esc(JSON.stringify(t.outputSchema, null, 2))}</pre>` +
    `<h3 style="margin-top:12px">Certification history</h3>${(cert.history || []).length ? `<table class="tbl"><tbody>${cert.history.slice().reverse().map(h => `<tr><td>${when(h.at)}</td><td>${esc(h.status)}</td><td class="muted">${esc(h.basis)}, ε = ${h.eps}</td></tr>`).join("")}</tbody></table>` : '<p class="muted small">No certification run yet.</p>'}`;
}
ACTIONS["open-tool"] = el => { const t = byId(S().tools, el.dataset.id); if (!t) return; if (UI.page !== "tools") location.hash = "tools"; setTimeout(() => openDrawer(t.name, toolDetail(t), null, "", `<button class="btn" data-action="edit-tool" data-id="${esc(t.id)}">Edit</button><button class="btn danger" data-action="del-tool" data-id="${esc(t.id)}">Delete</button>`), UI.page !== "tools" ? 60 : 0); };
ACTIONS["edit-tool"] = el => {
  const st = S(); const t = el.dataset.id ? byId(st.tools, el.dataset.id) : { id: "", serverId: (st.servers[0] || {}).id, name: "", description: "", inputArtefacts: [], outputArtefacts: [], inputCategories: ["ID"], tokens: 220, qos: { latencyS: 1, price: 0, dependability: 0.98 }, declared: { forwards: false, retains: [], attested: false } };
  if (!st.servers.length) return toast("Add an MCP server first.", true);
  const arts = st.config.artefacts.map(a => [a.id, a.name]); const cats = st.config.dataCategories.map(c => [c.id, c.name]);
  openDrawer(el.dataset.id ? "Edit tool" : "Add tool", `<div class="form-grid">${input("id", "Identifier", t.id, { hint: "For example muni.attestation.get" })}${select("serverId", "MCP server", t.serverId, st.servers.map(s => [s.id, s.name + " (" + orgName(s.orgId) + ")"]))}${input("name", "Name", t.name, { full: true })}${input("description", "Description shown to the agent", t.description, { textarea: true, full: true })}${checks("ins", "Input artefacts", t.inputArtefacts, arts, { full: true })}${checks("outs", "Output artefacts", t.outputArtefacts, arts, { full: true })}${checks("cats", "Personal data it receives", t.inputCategories, cats, { full: true })}${input("tokens", "Context cost (tokens)", t.tokens, { type: "number" })}${input("latency", "Latency (s)", t.qos.latencyS, { type: "number", step: "0.1" })}${input("price", "Price (€)", t.qos.price, { type: "number" })}${input("dep", "Dependability", t.qos.dependability, { type: "number", step: "0.001" })}${checks("retains", "Declared: data the tool returns", t.declared.retains, cats, { full: true })}<label class="check full"><input type="checkbox" name="forwards" ${t.declared.forwards ? "checked" : ""}> Declared: forwards data outside its organization</label><label class="check full"><input type="checkbox" name="attested" ${t.declared.attested ? "checked" : ""}> The provider attests these declarations</label></div>`, form => {
    const id = fv(form, "id"); if (!/^[A-Za-z0-9_.-]{3,64}$/.test(id)) { fieldErr(form, "id", "Use 3 to 64 letters, digits, dots, dashes or underscores."); return false; }
    if (!el.dataset.id && byId(st.tools, id)) { fieldErr(form, "id", "This identifier already exists."); return false; }
    if (!fv(form, "name")) { fieldErr(form, "name", "Enter a name."); return false; }
    if (fv(form, "description").length < 10) { fieldErr(form, "description", "Describe what the tool does (the agent reads this text)."); return false; }
    const n = k => Number(fv(form, k)); if (!(n("tokens") > 0)) { fieldErr(form, "tokens", "Enter a positive number."); return false; } const dep = n("dep"); if (!(dep > 0 && dep <= 1)) { fieldErr(form, "dep", "Enter a value between 0 and 1."); return false; }
    Store.commit(s => { const srv = byId(s.servers, fv(form, "serverId")); const declared = { forwards: fv(form, "forwards"), retains: fvAll(form, "retains"), attested: fv(form, "attested") };
      const x = { ...(el.dataset.id ? byId(s.tools, t.id) : {}), id: el.dataset.id || id, serverId: srv.id, orgId: srv.orgId, name: fv(form, "name"), description: fv(form, "description"), inputArtefacts: fvAll(form, "ins"), outputArtefacts: fvAll(form, "outs"), inputCategories: fvAll(form, "cats"), tokens: n("tokens"), qos: { latencyS: n("latency") || 0, price: n("price") || 0, dependability: dep }, declared, demo: false };
      x.inputSchema = { type: "object", properties: Object.fromEntries(x.inputArtefacts.map(a => [a, { type: "string" }]).concat([["applicant_id", { type: "string" }]])), required: ["applicant_id"].concat(x.inputArtefacts) };
      x.outputSchema = { type: "object", properties: Object.fromEntries((x.outputArtefacts.length ? x.outputArtefacts : ["status"]).map(a => [a, { type: "string" }])) };
      if (!el.dataset.id) { x.truth = { forwards: declared.forwards, retains: declared.retains }; x.card = null; x.certification = { status: "uncertified", score: null, audited: false, attested: declared.attested, history: [] }; s.tools.push(x); }
      else { const changed = JSON.stringify(byId(s.tools, x.id).declared) !== JSON.stringify(declared) || byId(s.tools, x.id).description !== x.description; Object.assign(byId(s.tools, x.id), x); if (changed) { const tt = byId(s.tools, x.id); if (tt.card) tt.card.status = "outdated"; if (tt.certification.status === "certified") { tt.certification.status = "uncertified"; tt.certification.basis = "declarations changed"; } } }
      Store.log("tool", `Tool ${x.id} saved`); });
    toast(el.dataset.id ? "Tool saved; regenerate its card if the description changed" : "Tool added; generate its card in the preparation center");
  });
  if (el.dataset.id) document.querySelector('#drawer [name="id"]').readOnly = true;
};
ACTIONS["del-tool"] = el => { const id = el.dataset.id; confirmDialog(`Delete the tool ${id}?`, "Delete tool", () => { closeDrawer(); Store.commit(s => { s.tools = s.tools.filter(t => t.id !== id); Store.log("tool", `Tool ${id} deleted`); }); toast("Tool deleted"); }); };

/* ================================================== 5 · Service descriptors */
RENDER.descriptors = () => {
  const st = S(); const f = UI.descFilter; const q = f.q.toLowerCase();
  const ds = st.descriptors.filter(d => (!q || (d.id + " " + d.name + " " + d.description).toLowerCase().includes(q)) && (!f.org || d.orgId === f.org));
  const nodes = st.descriptors.map(d => d.id); const edges = [];
  st.descriptors.forEach(d => d.requires.forEach(a => st.descriptors.filter(x => x.delivers.includes(a)).forEach(x => edges.push({ from: x.id, to: d.id, label: artName(a) }))));
  return head("Service descriptors", "What each organization declares it can do: required inputs, produced outputs, capabilities and mandatory companions. Derivation chains descriptors through their artefacts.", `<button class="btn primary" data-action="edit-desc">Add descriptor</button>`) +
    `<section class="panel" style="margin-bottom:16px"><div class="panel-h" style="gap:8px;flex-wrap:wrap"><input type="text" placeholder="Search descriptors" aria-label="Search descriptors" value="${esc(f.q)}" data-filter="desc.q" style="max-width:260px"><select aria-label="Organization" data-filter="desc.org" style="max-width:220px"><option value="">All organizations</option>${st.organizations.map(o => `<option value="${o.id}" ${f.org === o.id ? "selected" : ""}>${esc(o.name)}</option>`).join("")}</select><span class="sub">${ds.length} of ${st.descriptors.length}</span></div>
    <div class="tbl-wrap"><table class="tbl"><thead><tr><th>Descriptor</th><th>Organization</th><th>Requires</th><th>Produces</th><th>Capabilities</th><th>Companions</th><th class="num">Associated tools</th></tr></thead><tbody>${ds.map(d => { const tools = st.tools.filter(t => t.card && d.capabilities.some(r => (t.card.caps[r] || 0) >= st.config.params.tauMu)); return `<tr class="click" data-action="open-desc" data-id="${d.id}" tabindex="0"><td><b>${esc(d.name)}</b><br><code class="muted">${esc(d.id)}</code></td><td>${esc(orgName(d.orgId))}</td><td>${d.requires.map(a => `<span class="tag">${esc(artName(a))}</span>`).join("") || "–"}</td><td>${d.delivers.map(a => `<span class="tag">${esc(artName(a))}</span>`).join("")}</td><td>${d.capabilities.map(r => `<span class="tag">${esc(capById(r).name)}</span>`).join("")}</td><td>${d.companions.map(c => `<code>${esc(c)}</code>`).join(", ") || "–"}</td><td class="num">${tools.length}</td></tr>`; }).join("") || `<tr><td colspan="7"><div class="empty"><b>No descriptor matches</b>Clear the search or add a descriptor.</div></td></tr>`}</tbody></table></div></section>` +
    panel("Dependencies between descriptors", graphSVG(nodes, edges, id => { const d = byId(st.descriptors, id); return [d.name, orgName(d.orgId)]; }, { aria: "Dependency graph of the service descriptors", noList: true }), { sub: "An arrow means that a document produced by one procedure is required by the other. Click a node to open it." });
};
AFTER.descriptors = () => document.querySelectorAll(".gnode").forEach(n => n.addEventListener("click", () => ACTIONS["open-desc"]({ dataset: { id: n.dataset.node } })));
function descDetail(d) {
  const st = S(); const tools = st.tools.filter(t => t.card && d.capabilities.some(r => (t.card.caps[r] || 0) > 0));
  const hand = d.requires.map(a => { const p = st.descriptors.filter(x => x.delivers.includes(a)); return `<tr><td>${esc(artName(a))}</td><td>${p.length ? p.map(x => esc(x.name)).join("<br>") : (byId(st.config.artefacts, a) || {}).usuallyHeld ? '<span class="muted">Held by the requester</span>' : '<span class="fail">No producer</span>'}</td><td class="num">${p.length ? fmt(Derivation.alignment(a, a)) : "–"}</td></tr>`; }).join("");
  return `<dl class="kv"><dt>Identifier</dt><dd><code>${esc(d.id)}</code></dd><dt>Organization</dt><dd>${esc(orgName(d.orgId))} ${prov("declared")}</dd><dt>Description</dt><dd>${esc(d.description)}</dd><dt>Purpose</dt><dd>${esc(d.purpose)}</dd><dt>Personal data elicited</dt><dd>${d.elicited.map(x => `<span class="tag">${esc(x)}</span>`).join("")}</dd><dt>Preconditions</dt><dd>${esc(d.preconditions || "None")}</dd><dt>Fee, duration</dt><dd>${d.fee} €, ${d.durationDays} day(s)</dd><dt>Companions</dt><dd>${d.companions.map(c => esc((byId(st.descriptors, c) || {}).name || c)).join(", ") || "None"}</dd><dt>Source</dt><dd>${esc(d.record || "–")}</dd></dl>` +
    `<h3 style="margin-top:14px">Inputs and their producers</h3><table class="tbl"><thead><tr><th>Required artefact</th><th>Produced by</th><th class="num">Alignment</th></tr></thead><tbody>${hand || '<tr><td colspan="3" class="muted">No input</td></tr>'}</tbody></table>` +
    `<h3 style="margin-top:14px">Capabilities and associated tools</h3>${d.capabilities.map(r => `<div style="margin-bottom:8px"><b>${esc(capById(r).name)}</b><div class="chips">${tools.filter(t => (t.card.caps[r] || 0) > 0).map(t => `<span class="tag">${esc(t.id)} · μ ${fmt(t.card.caps[r])}</span>`).join("") || '<span class="fail small">No tool maps to this capability</span>'}</div></div>`).join("")}`;
}
ACTIONS["open-desc"] = el => { const d = byId(S().descriptors, el.dataset.id); if (!d) return; if (UI.page !== "descriptors") location.hash = "descriptors"; setTimeout(() => openDrawer(d.name, descDetail(d), null, "", `<button class="btn" data-action="edit-desc" data-id="${d.id}">Edit</button><button class="btn danger" data-action="del-desc" data-id="${d.id}">Delete</button>`), UI.page !== "descriptors" ? 60 : 0); };
ACTIONS["edit-desc"] = el => {
  const st = S(); const d = el.dataset.id ? byId(st.descriptors, el.dataset.id) : { id: "", orgId: (st.organizations[0] || {}).id, name: "", description: "", purpose: st.config.purposes[0], requires: [], delivers: [], capabilities: [], companions: [], elicited: ["ID"], fee: 0, durationDays: 1, preconditions: "", record: "" };
  const arts = st.config.artefacts.map(a => [a.id, a.name]);
  openDrawer(el.dataset.id ? "Edit descriptor" : "Add descriptor", `<div class="form-grid">${input("id", "Identifier", d.id, { hint: "For example d-site" })}${select("orgId", "Organization", d.orgId, st.organizations.map(o => [o.id, o.name]))}${input("name", "Name", d.name, { full: true })}${input("description", "Description", d.description, { textarea: true, full: true })}${select("purpose", "Purpose", d.purpose, st.config.purposes.map(p => [p, p]))}${input("preconditions", "Preconditions", d.preconditions)}${checks("requires", "Required inputs", d.requires, arts, { full: true })}${checks("delivers", "Produced outputs", d.delivers, arts, { full: true })}${checks("caps", "Capabilities required to enact it", d.capabilities, st.config.capabilities.map(c => [c.id, c.name]), { full: true })}${checks("comp", "Mandatory companion descriptors", d.companions, st.descriptors.filter(x => x.id !== d.id).map(x => [x.id, x.name]), { full: true })}${checks("elic", "Personal data elicited from the requester", d.elicited, st.config.dataCategories.map(c => [c.id, c.name]), { full: true })}${input("fee", "Fee (€)", d.fee, { type: "number" })}${input("dur", "Duration (days)", d.durationDays, { type: "number" })}</div>`, form => {
    const id = fv(form, "id"); if (!/^[a-z0-9-]{2,40}$/.test(id)) { fieldErr(form, "id", "Use lower-case letters, digits and dashes."); return false; }
    if (!el.dataset.id && byId(st.descriptors, id)) { fieldErr(form, "id", "This identifier already exists."); return false; }
    if (!fv(form, "name")) { fieldErr(form, "name", "Enter a name."); return false; }
    if (!fvAll(form, "delivers").length) { fieldErr(form, "description", "Select at least one produced output."); return false; }
    if (!fvAll(form, "caps").length) { fieldErr(form, "description", "Select at least one capability."); return false; }
    if (fvAll(form, "delivers").some(a => fvAll(form, "requires").includes(a))) { fieldErr(form, "description", "A descriptor cannot require what it produces."); return false; }
    Store.commit(s => { const x = { ...d, id: el.dataset.id || id, orgId: fv(form, "orgId"), name: fv(form, "name"), description: fv(form, "description"), purpose: fv(form, "purpose"), preconditions: fv(form, "preconditions"), requires: fvAll(form, "requires"), delivers: fvAll(form, "delivers"), capabilities: fvAll(form, "caps"), companions: fvAll(form, "comp"), elicited: fvAll(form, "elic"), fee: Number(fv(form, "fee")) || 0, durationDays: Number(fv(form, "dur")) || 1, demo: false };
      const i = s.descriptors.findIndex(y => y.id === x.id); if (i >= 0) s.descriptors[i] = x; else s.descriptors.push(x); Store.log("desc", `Descriptor ${x.id} saved`); });
    toast("Descriptor saved");
  });
  if (el.dataset.id) document.querySelector('#drawer [name="id"]').readOnly = true;
};
ACTIONS["del-desc"] = el => { const id = el.dataset.id; confirmDialog(`Delete the descriptor ${id}?`, "Delete descriptor", () => { closeDrawer(); Store.commit(s => { s.descriptors = s.descriptors.filter(d => d.id !== id); s.descriptors.forEach(d => d.companions = d.companions.filter(c => c !== id)); Store.log("desc", `Descriptor ${id} deleted`); }); toast("Descriptor deleted"); }); };
